const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function timeInput({id,name='',value='00:00',disabled=false,label='tiempo de cámara'}){const [m='',s='']=String(value).split(':');return `<span class="clock-entry" data-clock="${escape(id)}"><input type="hidden" id="${escape(id)}" ${name?`name="${escape(name)}"`:''} value="${escape(value)}"><input class="clock-min" type="text" inputmode="numeric" maxlength="4" value="${escape(m)}" aria-label="Minutos de ${escape(label)}" ${disabled?'disabled':''} data-clock-part="minutes"><span class="clock-colon" aria-hidden="true">:</span><input class="clock-sec" type="text" inputmode="numeric" maxlength="2" value="${escape(s)}" aria-label="Segundos de ${escape(label)}" ${disabled?'disabled':''} data-clock-part="seconds"><button type="button" class="clock-long" title="Activar escritura de tres o cuatro cifras para tiempos de cámara superiores a 99 minutos" aria-label="Minutos de tres o cuatro cifras" ${disabled?'disabled':''}>100+</button></span>`;}
export function installClocks(){
 function update(wrapper,commit){const m=wrapper.querySelector('.clock-min'),s=wrapper.querySelector('.clock-sec'),hidden=wrapper.querySelector('input[type=hidden]');hidden.value=m.value===''&&s.value===''?'':`${m.value||'00'}:${(s.value||'0').padStart(2,'0')}`;if(commit){wrapper.dataset.committed=hidden.value;hidden.dispatchEvent(new Event('change',{bubbles:true}));}}
 document.addEventListener('click',e=>{if(e.target.closest('.clock-long')){const wrapper=e.target.closest('.clock-entry');wrapper.dataset.long=wrapper.dataset.long==='yes'?'no':'yes';e.target.setAttribute('aria-pressed',String(wrapper.dataset.long==='yes'));wrapper.querySelector('.clock-min').focus();wrapper.querySelector('.clock-min').select();}});
 document.addEventListener('input',e=>{const part=e.target.dataset.clockPart;if(!part)return;const wrapper=e.target.closest('.clock-entry'),id=wrapper.dataset.clock,caret=e.target.selectionStart;const clean=e.target.value.replace(/\D/g,'');if(clean!==e.target.value){e.target.value=clean;e.target.setSelectionRange(Math.min(caret,clean.length),Math.min(caret,clean.length));}const jump=part==='minutes'&&wrapper.dataset.long!=='yes'&&e.target.value.length===2;const done=jump||(part==='seconds'&&e.target.value.length===2);update(wrapper,done);const fresh=document.querySelector(`[data-clock="${CSS.escape(id)}"]`);if(fresh&&done){const field=fresh.querySelector('.clock-sec');field.focus();if(jump)field.select();else field.setSelectionRange(field.value.length,field.value.length);}});
 document.addEventListener('paste',e=>{const wrapper=e.target.closest('.clock-entry');if(!wrapper)return;const data=e.clipboardData?.getData('text')?.trim();if(/^\d{1,4}:[0-5]\d$/.test(data)){e.preventDefault();const [m,s]=data.split(':');wrapper.querySelector('.clock-min').value=m;wrapper.querySelector('.clock-sec').value=s;update(wrapper,true);}});
 document.addEventListener('focusout',e=>{const wrapper=e.target.closest('.clock-entry');if(!wrapper)return;setTimeout(()=>{if(!wrapper.isConnected||wrapper.contains(document.activeElement))return;const hidden=wrapper.querySelector('input[type=hidden]');update(wrapper,false);if(hidden.value!==wrapper.dataset.committed)update(wrapper,true);},0);});
}
